package vn.boardinghub.modules.property;import vn.boardinghub.shared.api.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/properties")public class PropertyController{private final PropertyService s;public PropertyController(PropertyService s){this.s=s;}@GetMapping public ApiResponse<List<PropertyDtos.Response>> list(){return ApiResponse.ok("Properties",s.list());}@GetMapping("/{id}")public ApiResponse<PropertyDtos.Response> get(@PathVariable Long id){return ApiResponse.ok("Property",s.get(id));}@PostMapping public ApiResponse<PropertyDtos.Response> create(@Valid @RequestBody PropertyDtos.Request r){return ApiResponse.ok("Property created",s.create(r));}@PutMapping("/{id}")public ApiResponse<PropertyDtos.Response> update(@PathVariable Long id,@Valid @RequestBody PropertyDtos.Request r){return ApiResponse.ok("Property updated",s.update(id,r));}@DeleteMapping("/{id}")public ApiResponse<Void> delete(@PathVariable Long id){s.delete(id);return ApiResponse.ok("Property deleted",null);}}
